B.a_c=new A.k(B.f,["N\xe4chstes Angebot gesch\xe4tzt um den {d}","Next deal estimated around {d}","Prossima promozione stimata verso il {d}","Pr\xf3xima oferta estimada hacia el {d}"],t.w)
